/** 21122-MUEVE-CUENTA y 21123-GRABA-CUENTA-1009. */
@Component
@RequiredArgsConstructor
public class CuentaPuente1503 {

    private final P108Properties.CuentaPuente cfg;
    private final CsiProceso csi;

    /** Solo origen 3 y solo si el esquema trae la cuenta genérica. */
    public AsientoContable ajusta(AsientoContable a, int origen) {
        if (origen == 3 && a.cuenta().equals(cfg.generica())) {
            a = a.conCuenta(cuentaPorCsi());
        }
        // RMC-CTA-DVR = 5: cuenta de orden, sin sector, actividad ni banca
        return (a.divisor() == 5) ? a.comoCuentaDeOrden() : a;
    }

    /** Transacciones 1009 y 3011 de origen 3: cargo (naturaleza 1) adicional a la cuenta puente. */
    public AsientoContable asientoCargo(GrupoContable g) {
        return AsientoContable.cargo(g, cuentaPorCsi(), /*tipoMov*/ 1, /*causa*/ 0);
    }

    private String cuentaPorCsi() {
        return cfg.csiLocal().contains(csi.actual()) ? cfg.cuentaLocal() : cfg.cuentaForanea();
    }
}

/** WS-TABLA-150301-F: moneda x producto x instrumento, PIC 9(14)V99 COMP. */
@Component
@JobScope
public class Acumulado4014 {

    private static final BigDecimal TOPE = new BigDecimal("99999999999999.99");
    private final Map<Celda, BigDecimal> totales = new HashMap<>();

    record Celda(int moneda, int producto, int instrumento) {}

    /** 21123-GRABA-CUENTA-4014. */
    public void suma(GrupoContable g) {
        int m = (g.moneda() == 1 || g.moneda() == 5) ? g.moneda() : 1;          // otra moneda cuenta como MN
        int p = switch (g.producto()) { case 1 -> 1; case 66 -> 2; default -> 3; };
        int i = (g.instrumento() > 0 && g.instrumento() < 100) ? g.instrumento() : 99;
        totales.merge(new Celda(m, p, i), g.importe(), (a, b) -> {
            BigDecimal s = a.add(b);                                             // escala 2: suma exacta
            if (s.compareTo(TOPE) > 0) throw new DesbordamientoAcumuladorException("4014", s);
            return s;
        });
    }

    public Map<Celda, BigDecimal> totales() { return Map.copyOf(totales); }
}
